ationLine;			// V102	ControlHandle hButtonCtl;			// V102};class TeamWindow : public InfoWindow{public:	TeamWindow(Target* aParent);	// V101	virtual ~TeamWindow();private:	static ConstStr255Param title;	static const short height;	static const short width;	static const InfoTextLine* text;	static const int nLines;	};#endif	